@Composable private fun AFMetric(label:String,value:String){Column(Modifier.width(70.dp)){Text(label,color=AF_MUTED,fontSize=7.sp);Text(value,color=AF_TEXT,fontSize=9.sp,fontWeight=FontWeight.Black)}}
@Composable private fun AFOhlc(c:Candle){Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(14.dp),colors=CardDefaults.cardColors(containerColor=AF_PANEL)){Row(Modifier.fillMaxWidth().padding(9.dp),horizontalArrangement=Arrangement.SpaceEvenly){Text("O ${afMoney(c.open)}",color=AF_TEXT,fontSize=8.sp);Text("H ${afMoney(c.high)}",color=AF_GREEN,fontSize=8.sp);Text("L ${afMoney(c.low)}",color=AF_RED,fontSize=8.sp);Text("C ${afMoney(c.close)}",color=AF_TEXT,fontSize=8.sp);Text("V ${afCompact(c.volume)}",color=AF_MUTED,fontSize=8.sp)}}}
@Composable private fun AFGauge(score:Int){Canvas(Modifier.size(125.dp)){for(i in 1..3)drawCircle(Color(0xFF1B2B3D),size.minDimension*.34f*i/3f,center,style=androidx.compose.ui.graphics.drawscope.Stroke(1f));drawCircle(if(score>=70)AF_RED else AF_PURPLE,size.minDimension*.18f,center);drawCircle(AF_CYAN,size.minDimension*.34f,center,style=androidx.compose.ui.graphics.drawscope.Stroke(2f))}}
@Composable private fun APSpark(values:List<Double>,modifier:Modifier){Canvas(modifier){if(values.size<2)return@Canvas;val lo=values.minOrNull()?:0.0;val hi=values.maxOrNull()?:1.0;val range=(hi-lo).takeIf{it>0}?:1.0;var last=Offset(0f,size.height);values.forEachIndexed{i,v->val p=Offset(size.width*i/values.lastIndex.toFloat(),size.height-((v-lo)/range*size.height).toFloat());if(i>0)drawLine(AF_CYAN,last,p,2f);last=p}}}
private fun afMoney(v:Double)=if(v>=1000)"%,.2f".format(v)else if(v>=1)"%.4f".format(v)else"%.8f".format(v)
private fun afPct(v:Double)="%+.2f%%".format(v)
private fun afCompact(v:Double)=when{v>=1e9->"%.1fB".format(v/1e9);v>=1e6->"%.1fM".format(v/1e6);v>=1e3->"%.1fK".format(v/1e3);else->"%.0f".format(v)}
